package io.chronos.handlers;
import io.chronos.common.RunContext; import org.springframework.stereotype.Component; import java.net.URI; import java.net.http.*; import java.time.Duration; import java.util.*;
@Component public class BuiltinHandlers { public List<JobHandler> all(){return List.of(new Sleep(),new Flaky(),new Email(),new Http());} static class Sleep implements JobHandler {public String type(){return "sleep-and-log";} public void handle(RunContext c)throws Exception{Thread.sleep(100);}} static class Flaky implements JobHandler {public String type(){return "flaky";} public void handle(RunContext c){if(Math.random()<.5)throw new IllegalStateException("configured flaky failure");}} static class Email implements JobHandler{public String type(){return "send-email-mock";}public void handle(RunContext c){System.out.println("mock email "+c.idempotencyKey());}} static class Http implements JobHandler{public String type(){return "http-call";}public void handle(RunContext c)throws Exception{HttpClient.newHttpClient().send(HttpRequest.newBuilder(URI.create("https://example.com")).timeout(Duration.ofSeconds(10)).GET().build(),HttpResponse.BodyHandlers.discarding());}} }
